/** PSG APEX native home launcher. Existing APEX services are only contacted, never modified. */
public class MainActivity extends Activity {
    static final int NAVY=Color.rgb(7,20,38), PANEL=Color.rgb(14,32,54), GOLD=Color.rgb(216,180,90), WHITE=Color.rgb(242,245,249), MUTED=0xffaab7c7;
    static final String[] PAGES={"Executive Home","Business HQ","Documents Vault","AI Command Centre","Communications","Personal & Family","Health & Fitness","Productivity","APEX Linux Mobile","Settings"};
    static final String[] PAGE_HINTS={"Your PSG command centre","Clients, jobs, quotes and invoices","Your files and documents","AI tools and assistants","Calls, messages and connected apps","Family, contacts and personal life","Health, focus and wellbeing","Planning and daily work","Existing Debian services and dashboard","Launcher preferences and device controls"};
    LinearLayout root, header, content, nav; ScrollView scroller; EditText search; TextView pageTitle, statusLine; int workspace=0; boolean rebuilding=false;
    final Handler handler=new Handler(Looper.getMainLooper()); SharedPreferences prefs; ExecutorService network=Executors.newSingleThreadExecutor();
    int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
    @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("psg_launcher",MODE_PRIVATE);workspace=Math.max(0,Math.min(9,prefs.getInt("workspace",0)));getWindow().setStatusBarColor(NAVY);getWindow().setNavigationBarColor(NAVY);buildShell();showPage(workspace);applySavedWallpaper();}
    GradientDrawable shape(int color,int stroke,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
    TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER_VERTICAL);return t;}
    LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    Button button(String label){Button b=new Button(this);b.setText(label);b.setTextColor(GOLD);b.setAllCaps(false);b.setTextSize(12);b.setBackground(shape(PANEL,0xff344962,12));b.setPadding(dp(5),dp(3),dp(5),dp(3));return b;}
    void buildShell(){
        root=column();root.setBackgroundColor(NAVY);setContentView(root);
        header=column();header.setPadding(dp(16),dp(8),dp(16),dp(7));root.addView(header);
        LinearLayout brandRow=row();header.addView(brandRow);
        TextView brand=text("PSG  /  APEX",22,GOLD);brand.setTypeface(null,1);brandRow.addView(brand,new LinearLayout.LayoutParams(0,-2,1));
        Button quick=button("☼  QUICK");quick.setOnClickListener(v->quickSettings());brandRow.addView(quick,new LinearLayout.LayoutParams(-2,dp(40)));
        TextView sub=text("PRO MAESTRO SOLUTIONS GROUP  •  COMMAND CENTRE",9,WHITE);header.addView(sub);
        search=new EditText(this);search.setSingleLine(true);search.setTextColor(WHITE);search.setHintTextColor(MUTED);search.setHint("Search apps or workspaces");search.setTextSize(14);search.setPadding(dp(13),0,dp(13),0);search.setBackground(shape(PANEL,GOLD,13));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,dp(44));sp.topMargin=dp(9);header.addView(search,sp);
        pageTitle=text(PAGES[workspace],19,GOLD);pageTitle.setTypeface(null,1);pageTitle.setPadding(dp(17),dp(7),dp(17),0);root.addView(pageTitle);
        TextView hint=text(PAGE_HINTS[workspace],11,MUTED);hint.setPadding(dp(18),0,dp(18),dp(5));hint.setTag("hint");root.addView(hint);
        scroller=new ScrollView(this);scroller.setFillViewport(true);content=column();content.setPadding(dp(13),dp(2),dp(13),dp(12));scroller.addView(content);root.addView(scroller,new LinearLayout.LayoutParams(-1,0,1));
        nav=row();nav.setPadding(dp(5),dp(5),dp(5),dp(5));nav.setBackgroundColor(0xff0b1b30);root.addView(nav);
        String[] labels={"Home","Business","Files","AI","Apps","System"};int[] targets={0,1,2,3,4,8};for(int i=0;i<labels.length;i++){final int p=targets[i];Button b=button(labels[i]);b.setTextSize(10);nav.addView(b,new LinearLayout.LayoutParams(0,dp(43),1));b.setOnClickListener(v->showPage(p));}
        search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){if(rebuilding)return;String q=s.toString().trim();if(q.isEmpty()){if(workspace==0)showPage(0);}else showSearchResults(q);}public void afterTextChanged(Editable e){}});
        final float[] down={0,0};root.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN){down[0]=e.getX();down[1]=e.getY();return true;}if(e.getAction()==MotionEvent.ACTION_UP){float dx=e.getX()-down[0],dy=e.getY()-down[1];if(Math.abs(dx)>dp(70)&&Math.abs(dx)>Math.abs(dy)){showPage((workspace+(dx<0?1:9))%10);return true;}}return false;});
    }
    void updateHint(){View v=root.findViewWithTag("hint");if(v instanceof TextView)((TextView)v).setText(PAGE_HINTS[workspace]);}
    void card(String title,String detail,Runnable action){LinearLayout c=column();c.setPadding(dp(13),dp(10),dp(13),dp(10));c.setBackground(shape(PANEL,0xff344962,14));TextView t=text(title,15,GOLD);t.setTypeface(null,1);c.addView(t);TextView d=text(detail,12,WHITE);d.setPadding(0,dp(3),0,0);c.addView(d);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(8);content.addView(c,lp);c.setOnClickListener(v->{if(action!=null)action.run();});}
    void heading(String s){TextView t=text(s,13,GOLD);t.setTypeface(null,1);t.setPadding(dp(3),dp(8),dp(3),dp(5));content.addView(t);}
    void showPage(int p){workspace=Math.max(0,Math.min(9,p));prefs.edit().putInt("workspace",workspace).apply();pageTitle.setText(PAGES[workspace]);updateHint();content.removeAllViews();rebuilding=true;search.setText("");rebuilding=false;
        switch(workspace){
        case 0:
            card("Welcome, Commander","PSG executive workspace • swipe horizontally to move between workspaces",()->showPage(1));
            heading("FAVOURITES");addFavouriteTiles();
            heading("COMMAND SHORTCUTS");card("Business HQ","Clients, jobs, quotes, invoices and suppliers",()->showPage(1));card("Documents Vault","Browse files using Android's file picker",()->showPage(2));card("AI Command Centre","Open installed AI assistants or web-based tools",()->showPage(3));card("Communications Centre","Phone, SMS and WhatsApp",()->showPage(4));card("APEX Linux Mobile","Check the existing backend and open its dashboard",()->showPage(8));card("Choose executive wallpaper","Use your PSG wallpaper or any image on this phone",()->chooseWallpaper());break;
        case 1:
            card("Business HQ","Open your existing local business service on port 8766",()->openPanel("http://127.0.0.1:8766/","Business HQ"));card("APEX Dashboard","Open the existing APEX dashboard on port 8080",()->openPanel("http://127.0.0.1:8080/","APEX Dashboard"));card("Client & Job Records","Use the current Business HQ interface; this launcher does not migrate or reset its database",()->openPanel("http://127.0.0.1:8766/","Business HQ"));card("Business data safety","Existing SQLite data and recovery backups are not modified by this launcher",()->info("Business data safety","The launcher only opens your existing service. It does not modify data/apex_business.db or your recovery snapshot."));break;
        case 2:
            card("Browse documents","Open Android's system document picker",()->openFiles());card("Downloads","Browse files available through Android storage access",()->openFolder("content://com.android.externalstorage.documents/document/primary%3ADownload"));card("APEX recovery backup","Your existing recovery snapshot remains outside this app and must be kept safe",()->info("Recovery backup","Expected existing archive: ~/apex-recovery/apex-snapshot-20261019-212550.tar.gz. This launcher does not alter it."));card("Linux file access","Android's file picker is provided here; direct proot filesystem browsing requires a separately configured Termux bridge",()->openFiles());break;
        case 3:
            card("Find an AI app","Search installed apps using the search field above",()->showPage(4));card("Open ChatGPT","Open ChatGPT if installed; otherwise use the browser",()->launchPackageOrUrl("com.openai.chatgpt","https://chatgpt.com"));card("Open browser","Launch your default web browser",()->openUrl("https://chatgpt.com"));card("AI workspace note","This launcher does not claim to embed an AI model locally",()->info("AI Command Centre","Use installed AI apps or online services. A local AI engine is not bundled in this source."));break;
        case 4:
            card("Phone / Dialer","Open the native Android dialer",()->launchDialer());card("SMS / Messages","Open your default SMS app",()->launchSms());card("WhatsApp","Open WhatsApp or WhatsApp Business",()->launchWhatsApp());card("Search installed apps","See all launchable apps with their real Android icons",()->showPage(9));break;
        case 5:
            card("Family & personal apps","Search installed contacts, calendar and messaging apps",()->showPage(9));card("Contacts","Open contacts app if installed",()->launchIntent(Intent.ACTION_VIEW,android.provider.ContactsContract.Contacts.CONTENT_URI));card("Calendar","Open your calendar app",()->launchPackageOrUrl("com.google.android.calendar","https://calendar.google.com"));card("Personal data separation","Personal/family information is not stored in the APEX business database by this launcher",()->info("Data separation","This launcher does not create or modify a family database."));break;
        case 6:
            card("Health & Fitness apps","Find installed health, activity and fitness apps",()->showPage(9));card("Focus settings","Open Android Digital Wellbeing settings when available",()->openSystemSettings("android.settings.DIGITAL_WELLBEING_SETTINGS"));card("Device settings","Open Android settings",()->startActivity(new Intent(Settings.ACTION_SETTINGS)));break;
        case 7:
            card("Calendar","Open your installed calendar",()->launchPackageOrUrl("com.google.android.calendar","https://calendar.google.com"));card("Tasks & notes","Find your installed productivity apps in the app drawer",()->showPage(9));card("Files","Open document picker",()->openFiles());card("Workspace navigation","Swipe left/right or use the bottom bar to switch workspace",()->info("Navigation","Ten workspaces are available. Workspace selection is saved automatically."));break;
        case 8:
            statusLine=text("APEX STATUS  •  checking not yet run",11,MUTED);content.addView(statusLine);card("Check backend health","GET http://127.0.0.1:8765/api/health",()->checkHealth());card("Open APEX Dashboard","http://127.0.0.1:8080/",()->openPanel("http://127.0.0.1:8080/","APEX Dashboard"));card("Open Business HQ","http://127.0.0.1:8766/",()->openPanel("http://127.0.0.1:8766/","Business HQ"));card("Open Termux","Launch the existing Termux app; Debian/proot must be started there",()->launchPackage("com.termux"));card("Termux:Widget","Open the widget app if installed; scripts are not executed by this launcher directly",()->launchPackage("com.termux.widget"));card("Linux files","Use Android's document picker for shared files",()->openFiles());card("Service safety","No service is stopped, restarted, or rewritten by this launcher",()->info("APEX safety","The launcher sends a read-only HTTP health request and opens existing local web panels."));break;
        case 9:
            card("Set as default launcher","Open Android Home settings and select PSG APEX Launcher",()->startActivity(new Intent(Settings.ACTION_HOME_SETTINGS)));card("Choose wallpaper","Select a photo or PSG executive wallpaper; selection is saved",()->chooseWallpaper());card("Quick settings","Open Android notification shade or device settings",()->quickSettings());card("Reset launcher preferences","Clear only this launcher's saved workspace and wallpaper selection",()->new AlertDialog.Builder(this).setTitle("Reset launcher preferences?").setMessage("This only clears this launcher's saved preferences. It does not touch APEX services or files.").setNegativeButton("Cancel",null).setPositiveButton("Reset",(d,w)->{prefs.edit().clear().apply();workspace=0;applySavedWallpaper();showPage(0);}).show());card("About this build","Native Java launcher source • Android 8+ target • Galaxy A20 Android 11 target",()->info("About PSG APEX","Source build only. Verify the generated APK on the target phone before relying on it as the default launcher."));card("Installed apps","Search and launch real installed Android apps",()->showPage(9));showAppsGrid("");break;
        }
    }
    void addFavouriteTiles(){String[] fav=prefs.getString("favorites","com.whatsapp,com.android.settings,com.termux").split(",");PackageManager pm=getPackageManager();boolean any=false;for(String pkg:fav){if(pkg.trim().isEmpty())continue;Intent i=pm.getLaunchIntentForPackage(pkg.trim());if(i!=null){String label=pm.getApplicationLabel(pm.getApplicationInfo(pkg.trim(),0)).toString();card(label,"Tap to open • long-press app tiles in Apps to pin/unpin",()->startActivity(i));any=true;}}if(!any)card("No favourites pinned","Open Apps and long-press an app to add it",()->showPage(9));}
    void showSearchResults(String q){content.removeAllViews();boolean found=false;String low=q.toLowerCase(Locale.ROOT);for(int i=0;i<PAGES.length;i++){if(PAGES[i].toLowerCase(Locale.ROOT).contains(low)||PAGE_HINTS[i].toLowerCase(Locale.ROOT).contains(low)){final int p=i;card(PAGES[i],PAGE_HINTS[i],()->showPage(p));found=true;}}showAppsGrid(q);if(!found&&content.getChildCount()==0)card("No results","Try another search term",null);}
    void showAppsGrid(String filter){PackageManager pm=getPackageManager();ArrayList<ApplicationInfo> apps=new ArrayList<>();try{for(ApplicationInfo a:pm.getInstalledApplications(PackageManager.GET_META_DATA)){if(pm.getLaunchIntentForPackage(a.packageName)!=null){String n=pm.getApplicationLabel(a).toString();if(n.toLowerCase(Locale.ROOT).contains(filter.toLowerCase(Locale.ROOT)))apps.add(a);}}}catch(Exception ignored){}Collections.sort(apps,(a,b)->pm.getApplicationLabel(a).toString().compareToIgnoreCase(pm.getApplicationLabel(b).toString()));if(apps.isEmpty()){if(!filter.isEmpty())card("No matching apps","Try another search term",null);return;}heading("INSTALLED APPS  •  LONG-PRESS TO PIN FAVOURITE");for(int i=0;i<apps.size();i+=3){LinearLayout r=row();for(int j=i;j<Math.min(i+3,apps.size());j++){ApplicationInfo a=apps.get(j);LinearLayout cell=column();cell.setGravity(Gravity.CENTER);cell.setPadding(dp(3),dp(7),dp(3),dp(7));ImageView icon=new ImageView(this);try{icon.setImageDrawable(pm.getApplicationIcon(a));}catch(Exception ignored){}LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(dp(42),dp(42));cell.addView(icon,ip);TextView label=text(pm.getApplicationLabel(a).toString(),11,WHITE);label.setGravity(Gravity.CENTER);label.setMaxLines(2);label.setPadding(0,dp(4),0,0);cell.addView(label);r.addView(cell,new LinearLayout.LayoutParams(0,dp(92),1));cell.setOnClickListener(v->{Intent in=pm.getLaunchIntentForPackage(a.packageName);if(in!=null)try{startActivity(in);}catch(Exception e){toast("Could not open app");}});cell.setOnLongClickListener(v->{toggleFavourite(a.packageName,pm.getApplicationLabel(a).toString());return true;});}LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);content.addView(r,rp);}}
    void toggleFavourite(String pkg,String label){LinkedHashSet<String> set=new LinkedHashSet<>();String saved=prefs.getString("favorites","com.whatsapp,com.android.settings,com.termux");for(String s:saved.split(","))if(!s.trim().isEmpty())set.add(s.trim());if(set.contains(pkg)){set.remove(pkg);toast(label+" removed from favourites");}else{set.add(pkg);toast(label+" pinned to Home");}prefs.edit().putString("favorites",join(set)).apply();}
    String join(Set<String> s){StringBuilder b=new StringBuilder();for(String v:s){if(b.length()>0)b.append(',');b.append(v);}return b.toString();}
    void quickSettings(){new AlertDialog.Builder(this).setTitle("PSG Quick Controls").setItems(new String[]{"Android Settings","Home settings / default launcher","APEX service health","Choose wallpaper","Installed apps"},(d,w)->{switch(w){case 0:startActivity(new Intent(Settings.ACTION_SETTINGS));break;case 1:startActivity(new Intent(Settings.ACTION_HOME_SETTINGS));break;case 2:checkHealth();break;case 3:chooseWallpaper();break;case 4:showPage(9);break;}}).show();}
    void launchDialer(){try{startActivity(new Intent(Intent.ACTION_DIAL,Uri.parse("tel:")));}catch(Exception e){toast("No phone dialer found");}}
    void launchSms(){try{startActivity(new Intent(Intent.ACTION_SENDTO,Uri.parse("smsto:")));}catch(Exception e){toast("No SMS app found");}}
    void launchWhatsApp(){if(!launchPackage("com.whatsapp"))launchPackage("com.whatsapp.w4b");}
    boolean launchPackage(String pkg){Intent i=getPackageManager().getLaunchIntentForPackage(pkg);if(i!=null){try{startActivity(i);return true;}catch(Exception ignored){}}toast("App not installed: "+pkg);return false;}
    void launchPackageOrUrl(String pkg,String url){if(!launchPackage(pkg))openUrl(url);}
    void launchIntent(String action,Uri uri){try{startActivity(new Intent(action,uri));}catch(Exception e){toast("No compatible app found");}}
    void openSystemSettings(String action){try{startActivity(new Intent(action));}catch(Exception e){startActivity(new Intent(Settings.ACTION_SETTINGS));}}
    void chooseWallpaper(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(i,41);}catch(Exception e){toast("Image picker unavailable");}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==41&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri u=data.getData();try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}prefs.edit().putString("wallpaper",u.toString()).apply();applySavedWallpaper();toast("Wallpaper saved");}}
    void applySavedWallpaper(){if(root==null)return;String value=prefs.getString("wallpaper",null);if(value==null){root.setBackgroundColor(NAVY);return;}try(InputStream in=getContentResolver().openInputStream(Uri.parse(value))){Drawable d=Drawable.createFromStream(in,null);if(d!=null)root.setBackground(d);else root.setBackgroundColor(NAVY);}catch(Exception e){root.setBackgroundColor(NAVY);}}
    void openFiles(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);try{startActivity(i);}catch(Exception e){toast("Android file picker unavailable");}}
    void openFolder(String uri){openFiles();}
    void openPanel(String url,String title){Intent i=new Intent(this,PanelActivity.class);i.putExtra("url",url);i.putExtra("title",title);startActivity(i);}
    void openUrl(String url){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){toast("No browser available");}}
    void checkHealth(){toast("Checking APEX backend…");network.execute(()->{String msg;try{HttpURLConnection c=(HttpURLConnection)new URL("http://127.0.0.1:8765/api/health").openConnection();c.setConnectTimeout(2500);c.setReadTimeout(2500);int code=c.getResponseCode();InputStream in=code<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[1024];int n;while(in!=null&&(n=in.read(buf))>0)out.write(buf,0,n);if(in!=null)in.close();msg="HTTP "+code+"\n"+out.toString("UTF-8");c.disconnect();}catch(Exception e){msg="Backend unreachable at 127.0.0.1:8765. Start existing APEX services in Termux first.\n"+e.getClass().getSimpleName();}final String m=msg;runOnUiThread(()->new AlertDialog.Builder(this).setTitle("APEX System Status").setMessage(m).setPositiveButton("OK",null).show());});}
    void info(String title,String message){new AlertDialog.Builder(this).setTitle(title).setMessage(message).setPositiveButton("OK",null).show();}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
    @Override public void onBackPressed(){if(workspace!=0){showPage(0);}else super.onBackPressed();}
    @Override protected void onDestroy(){super.onDestroy();network.shutdownNow();}
}
